import java.util.ArrayList;
import java.util.List;

/**
 * ============================================================================
 *  DO NOT EDIT THIS FILE. It is how you check your own work.
 * ============================================================================
 *
 *  Run it, from this folder:
 *      javac *.java
 *      java Verify
 *
 *  Both commands, after every edit. Up-arrow twice to repeat them.
 *
 *  There are 24 checks. When all 24 pass you are done with the exercise.
 *
 *  Some checks are STRUCTURAL — they ask the JVM questions about your types
 *  ("is Order actually a record?", "is PaymentResult actually sealed?", "are
 *  all three outcomes records?"). Others are BEHAVIOURAL — they call your code
 *  and compare the answer. You need both: code that behaves correctly but is
 *  not built from the right types has missed the point of the session, and
 *  the structural checks are here to say so.
 */
public class Verify {

    private static int passed = 0;
    private static final List<String> failures = new ArrayList<>();

    static void check(String name, boolean condition) {
        if (condition) { passed++; System.out.println("  PASS  " + name); }
        else { failures.add(name); System.out.println("  FAIL  " + name); }
    }

    static void checkEquals(String name, Object expected, Object actual) {
        boolean ok = expected == null ? actual == null : expected.equals(actual);
        if (ok) { passed++; System.out.println("  PASS  " + name); }
        else {
            failures.add(name);
            System.out.println("  FAIL  " + name);
            System.out.println("          expected: " + show(expected));
            System.out.println("          actual:   " + show(actual));
            hintOnWhitespace(expected, actual);
        }
    }

    /** Rejects when the code does NOT throw — used for the compact constructor. */
    static void checkThrows(String name, Runnable body) {
        try {
            body.run();
            failures.add(name);
            System.out.println("  FAIL  " + name + "  (nothing was thrown)");
        } catch (IllegalArgumentException e) {
            passed++;
            System.out.println("  PASS  " + name);
        } catch (RuntimeException e) {
            failures.add(name);
            System.out.println("  FAIL  " + name
                    + "  (threw " + e.getClass().getSimpleName()
                    + ", expected IllegalArgumentException)");
        }
    }

    static String show(Object o) {
        return o == null ? "null" : "\"" + o.toString()
                .replace("\n", "\\n")
                .replace("\t", "\\t") + "\"";
    }

    /**
     * The two text-block checks fail for invisible reasons more often than for
     * any other. If the only difference is whitespace, say so out loud rather
     * than leaving the student comparing two identical-looking strings.
     */
    static void hintOnWhitespace(Object expected, Object actual) {
        if (!(expected instanceof String e) || !(actual instanceof String a)) return;
        if (e.replaceAll("\\s", "").equals(a.replaceAll("\\s", ""))) {
            System.out.println("          ^ the text is right; only the WHITESPACE differs.");
            System.out.println("            Almost always the closing \"\"\" is in the wrong");
            System.out.println("            column, or there is one \\n too many at the end.");
        }
    }

    public static void main(String[] args) {
        System.out.println();
        System.out.println("Session 2 - Modernise the order domain");
        System.out.println("======================================");
        System.out.println();

        step1_recordStructure();
        step1_compactConstructor();
        step1_withDiscount();
        step2_sealed();
        step2_gatewayRules();
        step3_describe();
        step4_receipt();
        step5_summaryJson();

        summary();
    }

    // ---------------------------------------------------------------- STEP 1

    static void step1_recordStructure() {
        System.out.println("Step 1 - Order is a record");

        check("Order is a record, not a class",
                Order.class.isRecord());

        check("Order has exactly two components (customerEmail, total)",
                Order.class.isRecord() && Order.class.getRecordComponents().length == 2);

        // Value semantics come free with a record, and are the reason to use one.
        var a = new Order("alice@example.com", 250.00);
        var b = new Order("alice@example.com", 250.00);
        check("two Orders with the same values are equal",
                a.equals(b));
        check("...and hash to the same bucket",
                a.hashCode() == b.hashCode());

        System.out.println();
    }

    static void step1_compactConstructor() {
        System.out.println("Step 1 - the compact constructor guards construction");

        checkThrows("a blank email is rejected",
                () -> new Order("   ", 10.00));

        checkThrows("a null email is rejected",
                () -> new Order(null, 10.00));

        checkThrows("a negative total is rejected",
                () -> new Order("alice@example.com", -1.00));

        checkEquals("the email is normalised (trimmed and lower-cased)",
                "alice@example.com",
                new Order("  Alice@Example.COM  ", 10.00).customerEmail());

        System.out.println();
    }

    static void step1_withDiscount() {
        System.out.println("Step 1 - withDiscount returns a NEW Order");

        var original = new Order("alice@example.com", 250.00);
        var discounted = original.withDiscount(10);

        checkEquals("10% off 250.00 is 225.00",
                225.0, discounted.total());

        check("the original was not modified",
                original.total() == 250.00);

        System.out.println();
    }

    // ---------------------------------------------------------------- STEP 2

    static void step2_sealed() {
        System.out.println("Step 2 - PaymentResult is a closed set");

        check("PaymentResult is sealed",
                PaymentResult.class.isSealed());

        check("it permits exactly three outcomes",
                PaymentResult.class.isSealed()
                        && PaymentResult.class.getPermittedSubclasses().length == 3);

        boolean allRecords = PaymentResult.class.isSealed();
        if (allRecords) {
            for (Class<?> c : PaymentResult.class.getPermittedSubclasses()) {
                if (!c.isRecord()) { allRecords = false; break; }
            }
        }
        check("all three outcomes are records (so each is final, and each has equals)",
                allRecords);

        System.out.println();
    }

    static void step2_gatewayRules() {
        System.out.println("Step 2 - the gateway applies its rules in order");

        PaymentGateway gateway = new FakePaymentGateway();

        check("over the limit is Declined",
                gateway.charge(new Order("rich@example.com", 5000.00)) instanceof Declined);

        check("a nostock customer is OutOfStock",
                gateway.charge(new Order("nostock@example.com", 50.00)) instanceof OutOfStock);

        check("an ordinary order is Approved",
                gateway.charge(new Order("alice@example.com", 250.00)) instanceof Approved);

        // Rule ORDER matters: this customer is both over the limit and a
        // nostock address. The limit is checked first, so it must be Declined.
        check("the rules are applied in order, not whichever matches",
                gateway.charge(new Order("nostock@example.com", 5000.00)) instanceof Declined);

        System.out.println();
    }

    // ---------------------------------------------------------------- STEP 3

    static void step3_describe() {
        System.out.println("Step 3 - describe() renders each outcome");

        var reporter = new OrderReporter();

        checkEquals("Approved",
                "Approved: TX-1001",
                reporter.describe(new Approved("TX-1001")));

        checkEquals("Declined",
                "Declined: Amount exceeds limit",
                reporter.describe(new Declined("Amount exceeds limit")));

        checkEquals("OutOfStock",
                "Only 0 left of SKU-001",
                reporter.describe(new OutOfStock("SKU-001", 0)));

        System.out.println();
    }

    // ---------------------------------------------------------------- STEP 4

    static void step4_receipt() {
        System.out.println("Step 4 - the text block receipt (ends WITH a newline)");

        var reporter = new OrderReporter();

        // Written out with explicit \n so the indentation rule has nowhere to
        // hide. If this fails and the two strings look identical, count the
        // leading spaces — your closing """ is in the wrong column.
        String expectedApproved =
                  "RECEIPT\n"
                + "-------\n"
                + "Customer: alice@example.com\n"
                + "Total:    $250.00\n"
                + "Status:   Approved: TX-1001\n";

        checkEquals("the approved receipt matches exactly, including indentation",
                expectedApproved,
                reporter.receipt(new Order("alice@example.com", 250.00),
                                 new Approved("TX-1001")));

        // The same template, a different outcome. This one catches a receipt()
        // that hard-codes the status line instead of calling describe().
        String expectedDeclined =
                  "RECEIPT\n"
                + "-------\n"
                + "Customer: rich@example.com\n"
                + "Total:    $5000.00\n"
                + "Status:   Declined: Amount exceeds limit\n";

        checkEquals("the declined receipt uses the same template",
                expectedDeclined,
                reporter.receipt(new Order("rich@example.com", 5000.00),
                                 new Declined("Amount exceeds limit")));

        System.out.println();
    }

    // ---------------------------------------------------------------- STEP 5

    static void step5_summaryJson() {
        System.out.println("Step 5 - the JSON summary (ends WITHOUT a newline)");

        var reporter = new OrderReporter();

        String expectedApproved =
                  "{\n"
                + "  \"customer\": \"alice@example.com\",\n"
                + "  \"total\": 250.00,\n"
                + "  \"status\": \"Approved: TX-1001\"\n"
                + "}";

        checkEquals("the JSON matches exactly, and does NOT end in a newline",
                expectedApproved,
                reporter.summaryJson(new Order("alice@example.com", 250.00),
                                     new Approved("TX-1001")));

        String expectedOutOfStock =
                  "{\n"
                + "  \"customer\": \"nostock@example.com\",\n"
                + "  \"total\": 50.00,\n"
                + "  \"status\": \"Only 0 left of SKU-001\"\n"
                + "}";

        checkEquals("the JSON works for an out-of-stock order too",
                expectedOutOfStock,
                reporter.summaryJson(new Order("nostock@example.com", 50.00),
                                     new OutOfStock("SKU-001", 0)));

        System.out.println();
    }

    // ---------------------------------------------------------------- SUMMARY

    static void summary() {
        int total = passed + failures.size();
        System.out.println("---------------------------------------------------");
        if (failures.isEmpty()) {
            System.out.println("  ALL " + total + " CHECKS PASSED");
            System.out.println();
            System.out.println("  Note what the structural checks proved: not just that");
            System.out.println("  your code works, but that it is built from the right");
            System.out.println("  types. A sealed PaymentResult is a promise the compiler");
            System.out.println("  can keep. Next session you collect on it.");
        } else {
            System.out.println("  " + passed + "/" + total + " passed. Still to fix:");
            for (String f : failures) System.out.println("    - " + f);
        }
        System.out.println("---------------------------------------------------");
        System.out.println();
    }
}
